#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
public:
    Cat(string n) : name(n) {}
    virtual void speak() const {
        cout << name << "：" << endl;
    }
};

class OrangeCat : public Cat {
    int fish;
public:
    OrangeCat(string n, int f) : Cat(n), fish(f) {}
    void speak() const override {
        cout << name << "：我们是学生甲，处理了 " << fish << " 条，！" << endl;
    }
};

int main() {
    int f = 0;
    cin >> f;

    OrangeCat o("{name}", f);
    Cat& r = o;
    cout << "名称写「对象」，输出：";
    r.speak();
    cout << "写「学生甲」的名字，输出：";
    o.speak();
    return 0;
}
